<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { message } from 'ant-design-vue'
import type { TripPlan } from '@/types'
import { updateHistory } from '@/services/api'
import TripSummary from '@/components/TripSummary.vue'
import DayItinerary from '@/components/DayItinerary.vue'
import MapPanel from '@/components/MapPanel.vue'
const router = useRouter(); const raw = sessionStorage.getItem('tripPlan'); const id = Number(sessionStorage.getItem('tripPlanId') || 0); const plan = ref<TripPlan | null>(raw ? JSON.parse(raw) : null); const editMode = ref(false); const saving = ref(false); const snapshot = ref<TripPlan | null>(null)
const budget = computed(() => plan.value?.budget); const startEdit = () => { snapshot.value = plan.value ? JSON.parse(JSON.stringify(plan.value)) : null; editMode.value = true }; const cancelEdit = () => { if (snapshot.value) plan.value = snapshot.value; editMode.value = false }
const updateDay = (index: number, day: TripPlan['days'][number]) => { if (plan.value) plan.value.days = plan.value.days.map((item, i) => i === index ? day : item) }
const updateBudget = (key: keyof NonNullable<TripPlan['budget']>, value: string) => { if (plan.value?.budget) plan.value.budget = { ...plan.value.budget, [key]: Number(value) }; if (plan.value?.budget) plan.value.budget.total = plan.value.budget.total_attractions + plan.value.budget.total_hotels + plan.value.budget.total_meals + plan.value.budget.total_transportation }
const save = async () => { if (!plan.value || !id) { message.warning('只有历史行程可以保存修改'); return }; saving.value = true; try { await updateHistory(id, plan.value); sessionStorage.setItem('tripPlan', JSON.stringify(plan.value)); editMode.value = false; message.success('行程已保存') } catch (error: any) { message.error(error.message) } finally { saving.value = false } }
</script>
<template>
  <!-- review summary is inserted below the trip summary in the result layout -->
    <main v-if="plan" class="result-page page-container"><div class="result-toolbar"><button class="back-link" type="button" @click="router.push('/')">← 返回规划</button><div><button v-if="!editMode" class="outline-button" type="button" @click="startEdit">编辑行程</button><button v-if="editMode" class="outline-button" type="button" @click="cancelEdit">取消</button><button v-if="editMode" class="primary-small" type="button" :disabled="saving" @click="save">{{ saving ? '保存中…' : '保存修改' }}</button></div></div><TripSummary :plan="plan" /><div class="result-layout"><div><div class="section-title-row"><div><div class="eyebrow">THE ITINERARY</div><h2>每天，都值得期待</h2></div><span class="edit-tip" v-if="editMode">编辑模式已开启</span></div><DayItinerary v-for="(day, index) in plan.days" :key="day.day_index" :day="day" :edit-mode="editMode" @update="updateDay(index, $event)" /></div><aside class="result-aside"><div class="aside-card paper-card"><div class="eyebrow">ROUTE MAP</div><h3>一路向前</h3><MapPanel :days="plan.days" /></div><div v-if="plan.weather_info?.length" class="aside-card weather-card"><div class="eyebrow">WEATHER NOTES</div><h3>天气小贴士</h3><div v-for="weather in plan.weather_info" :key="weather.date" class="weather-row"><span>{{ weather.date.slice(5) }}</span><strong>{{ weather.forecast_available === false ? '暂无预报' : weather.day_weather }}</strong><span>{{ weather.forecast_available === false ? '—' : `${weather.day_temp}° / ${weather.night_temp}°` }}</span></div></div><div class="aside-card budget-card"><div class="eyebrow">ESTIMATED BUDGET</div><h3>预算预览</h3><div v-if="budget"><div class="budget-row"><span>门票</span><input v-if="editMode" class="edit-input budget-input" type="number" :value="budget.total_attractions" @input="updateBudget('total_attractions', ($event.target as HTMLInputElement).value)" /><strong v-else>¥{{ budget.total_attractions }}</strong></div><div class="budget-row"><span>住宿</span><input v-if="editMode" class="edit-input budget-input" type="number" :value="budget.total_hotels" @input="updateBudget('total_hotels', ($event.target as HTMLInputElement).value)" /><strong v-else>¥{{ budget.total_hotels }}</strong></div><div class="budget-row"><span>餐饮</span><input v-if="editMode" class="edit-input budget-input" type="number" :value="budget.total_meals" @input="updateBudget('total_meals', ($event.target as HTMLInputElement).value)" /><strong v-else>¥{{ budget.total_meals }}</strong></div><div class="budget-total"><span>合计</span><strong>¥{{ budget.total }}</strong></div></div><span v-else class="muted">暂无预算信息</span></div></aside></div></main><main v-else class="empty-page page-container"><div class="paper-card empty-card"><div class="empty-icon">✈</div><h2>还没有打开的行程</h2><p>先去规划一段属于你的旅程吧。</p><button class="primary-small" type="button" @click="router.push('/')">开始规划</button></div></main>
</template>
